pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        // ensure admissible: caller not zero and newOwner not zero
        vm.assume(caller != address(0) && newOwner != address(0));
        // ensure caller is not the current owner (we test non-owner access)
        address prevOwner = c.owner();
        vm.assume(caller != prevOwner);

        vm.prank(caller);
        bool success = true;
        try c.transferOwnership(newOwner) {} catch { success = false; }

        // The general rule: if a non-owner call to transferOwnership completes, the owner must remain unchanged.
        // The reference contract makes the call revert (success == false).
        // The buggy contract allows the call to succeed and changes owner.
        assertTrue(!success || c.owner() == prevOwner);
    }
}

